#!/bin/bash
# gen3.sh view tag : turnE_final/cand/<view>_s<tag>.png  (slim profiles + face fix), refs: front (design) + view-specific
cd /Users/waylonhuang/Documents/other/pixelart/swordswoman; v=$1; t=$2; T=v2/hair/turnE_final; o=$T/cand/${v}_s$t.png; [ -f $o ] && exit 0
HAIR="half-up shoulder-blade-length dark brown-black hair, a small knot with a red two-loop ribbon bow and two short tails on HER LEFT side-back of the head, side parting, soft side-swept bangs, thin tapered side locks"
FACE="the same cute face as the first image: very large sparkling anime eyes with highlights, small mouth with a gentle smile, soft small chin, soft round cheek, cheerful friendly expression (not sleepy, not sullen)"
SLIM="graceful SLIM Pokemon-trainer body seen from the side: SHALLOW body depth, a thin torso (front-to-back depth of the chest about the width of her neck plus a little), small flat chest, slim flat back, small hips with NO protruding bottom, slim thighs and calves, the red kimono skirt hangs straight and close to the body without a bustle or bulge, the wide sleeve hangs down by her side"
case $v in
iso_SE) W="3/4 front view: her body and face turn toward the LOWER-RIGHT of the picture (her nose points to the right side of the picture, we see more of her right cheek... the side of her face on the picture-right is the far side), seen from a camera 30 degrees ABOVE (top of the head visible, obi and hem curve downward). The bow on her left side-back is on the FAR side, peeking out behind the head on the picture-right"; R="$T/front.png $T/iso_S.png v2/design/turnE/rigref/iso_SE.png";;
left) W="STRICT 90-degree LEFT side PROFILE, eye-level: nose points at the LEFT edge of the picture, one eye visible; forehead curve, small nose bump, small lips, soft chin. $SLIM. The bow is on the NEAR side (visible on the back of her head)"; R="$T/front.png $T/prev/left.png v2/design/turnE/rigref/left.png";;
right) W="STRICT 90-degree RIGHT side PROFILE, eye-level: nose points at the RIGHT edge of the picture, one eye visible; forehead curve, small nose bump, small lips, soft chin. $SLIM. The bow is on the FAR side, only peeking above/behind the crown"; R="$T/front.png $T/prev/right.png v2/design/turnE/rigref/right.png";;
iso_E) W="STRICT 90-degree RIGHT side PROFILE seen from a camera 30 degrees ABOVE (top of the head visible, obi and hem curve slightly downward, boots seen slightly from above): nose points at the RIGHT edge, one eye visible; forehead curve, small nose bump, small lips, soft chin. $SLIM. The bow is on the FAR side, peeking above/behind the crown"; R="$T/front.png $T/prev/iso_E.png v2/design/turnE/rigref/iso_E.png";;
esac
P="Draw the EXACT same character as the FIRST image (same hair: $HAIR; same red short kimono-dress with wide short sleeves, grey-lavender obi, dark short boots; same head size, same flat cel style and colours), with $FACE, in this view: $W. The SECOND image is an earlier drawing of her in a similar view (use it for the pose, but fix the body to be slimmer and the face to be cuter). The THIRD image is a 3D render showing ONLY the camera angle and direction. Neutral relaxed standing pose. NO sword. Single full-body figure on a plain white background, no text."
for k in 1 2 3; do .venv/bin/python tools/gemini.py image "$P" $o $R > /dev/null 2>&1; [ -f $o ] && { mv ${o%.png}_1.png $T/alt/ 2>/dev/null; exit 0; }; sleep 30; done; echo FAIL $v $t
